@Service
public class OrderService {
    private final OrderRepository orderRepo;
    private final InventoryClient inventoryClient;

    public OrderResponse createOrder(OrderRequest request) {
        // Backend handles validation
        if (request.quantity() <= 0) {
            throw new InvalidOrderException("Quantity must be positive");
        }

        // Backend coordinates between systems
        var available = inventoryClient.checkStock(request.productId());
        if (!available) {
            throw new OutOfStockException("Product unavailable");
        }

        // Backend manages data persistence and consistency
        var order = new Order(request.productId(), request.quantity());
        orderRepo.save(order);

        return new OrderResponse(order.getId(), "PENDING");
    }
}
